#include "scheduler.h"

#include <assert.h>
#include <stdio.h>

static void test_pagination_composes_with_state_filter(void) {
    Scheduler s;
    scheduler_init(&s);

    /* 5 DONE, 3 FAILED */
    for (int i = 0; i < 5; i++) {
        int id = scheduler_submit(&s, 1, "done-job");
        int running_id;
        scheduler_run_next(&s, &running_id);
        scheduler_complete(&s, id);
    }
    for (int i = 0; i < 3; i++) {
        int id = scheduler_submit(&s, 1, "fail-job");
        int running_id;
        scheduler_run_next(&s, &running_id);
        scheduler_fail(&s, id);
    }

    Job page1[2];
    int total = 0;
    int written = scheduler_history_page(&s, 1, JOB_DONE, 1, 2, page1, &total);
    assert(total == 5);
    assert(written == 2);
    for (int i = 0; i < written; i++) {
        assert(page1[i].state == JOB_DONE);
    }

    Job page3[2];
    int total3 = 0;
    int written3 = scheduler_history_page(&s, 1, JOB_DONE, 3, 2, page3, &total3);
    assert(written3 == 1);

    Job bad[1];
    int t;
    assert(scheduler_history_page(&s, 0, JOB_DONE, 0, 2, bad, &t) == -1);
}

int main(void) {
    test_pagination_composes_with_state_filter();
    printf("PASS\n");
    return 0;
}

