#pragma once

#include "job.h"
#include "queue.h"

#define SCHEDULER_MAX_RUNNING 256
#define SCHEDULER_MAX_HISTORY 256

typedef struct {
    JobQueue pending;
    Job running[SCHEDULER_MAX_RUNNING];
    int running_count;
    Job history[SCHEDULER_MAX_HISTORY];
    int history_count;
} Scheduler;

void scheduler_init(Scheduler *s);
int scheduler_submit(Scheduler *s, int priority, const char *payload);
int scheduler_run_next(Scheduler *s, int *out_id);
int scheduler_complete(Scheduler *s, int id);
int scheduler_fail(Scheduler *s, int id);
int scheduler_find_state(const Scheduler *s, int id, JobState *out_state);

/*
 * Lists history entries (DONE/FAILED jobs), optionally filtered by
 * state, with pagination applied AFTER the filter. Writes up to
 * page_size matching jobs (newest-first is not required; history
 * order is fine) into out_jobs (caller-allocated array of at least
 * page_size). Writes the count of ALL matching entries (not just the
 * page) to *out_total. `has_filter` is 0 to list all history
 * regardless of state, 1 to filter by `filter_state`. page is
 * 1-based. Returns the number of jobs actually written to out_jobs,
 * or -1 on invalid page/page_size.
 */
int scheduler_history_page(const Scheduler *s, int has_filter, JobState filter_state,
                           int page, int page_size, Job *out_jobs, int *out_total);

